/**
 * 轻量级 Markdown 渲染器 (本地修复版)
 * 解决 Manifest V3 外部脚本加载限制，并增强正则匹配鲁棒性
 */
window.marked = {
    parse: function(text) {
        if (!text) return "";
        
        // 1. 基础转义 (防止注入)
        let html = text
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;");

        // 2. 图片: ![alt](url) - 支持中间换行和空格
        html = html.replace(/!\[([\s\S]*?)\]\s*\(([\s\S]*?)\)/gim, function(match, alt, url) {
            const cleanUrl = url.trim().replace(/\n/g, '');
            return `<img src="${cleanUrl}" alt="${alt}" style="max-width:100%; border-radius:4px; margin:8px 0; border:1px solid var(--border); display: block;">`;
        });
        
        // 3. 链接: [text](url) - 支持中间换行和空格
        html = html.replace(/\[([\s\S]*?)\]\s*\(([\s\S]*?)\)/gim, function(match, text, url) {
            const cleanUrl = url.trim().replace(/\n/g, '');
            return `<a href="${cleanUrl}" target="_blank" rel="noopener noreferrer" style="color:var(--primary); text-decoration:underline; font-weight:500;">${text}</a>`;
        });
        
        // 4. 标题 (需在行首)
        html = html.replace(/^### (.*$)/gim, '<h3 style="margin:12px 0 6px; color:var(--text-primary); border-bottom:1px solid var(--border); padding-bottom:4px;">$1</h3>');
        html = html.replace(/^## (.*$)/gim, '<h2 style="margin:16px 0 8px; color:var(--text-primary); border-bottom:1px solid var(--border); padding-bottom:6px;">$1</h2>');
        html = html.replace(/^# (.*$)/gim, '<h1 style="margin:20px 0 10px; color:var(--text-primary); border-bottom:1px solid var(--border); padding-bottom:8px;">$1</h1>');
        
        // 5. 粗体 & 斜体
        html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
        html = html.replace(/\*(.*?)\*/g, '<em>$1</em>');
        
        // 6. 行内代码
        html = html.replace(/`(.*?)`/g, '<code style="background:rgba(246,130,31,0.1); color:var(--primary); padding:2px 4px; border-radius:4px; font-family:monospace; font-size:0.9em;">$1</code>');
        
        // 7. 引用块
        html = html.replace(/^&gt; (.*$)/gim, '<div style="border-left:4px solid var(--primary); padding:4px 12px; margin:8px 0; background:rgba(255,255,255,0.03); color:var(--text-secondary); font-style:italic;">$1</div>');

        // 8. 列表符号
        html = html.replace(/^- (.*$)/gim, '<div style="display:flex; gap:8px; margin:4px 0;"><span style="color:var(--primary)">•</span><span>$1</span></div>');

        // 9. 表格处理 (简单实现)
        const tableRegex = /^\|(.+)\|[\r\n]+^\|([-| :]+)\|[\r\n]+((?:^\|(.+)\|$(?:[\r\n]+|$))+)/gm;
        html = html.replace(tableRegex, function(match, header, separator, body) {
            const getCells = (row) => row.replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim());
            const headers = getCells(header);
            const headerHtml = `<thead><tr>${headers.map(h => `<th style="border:1px solid var(--border); padding:6px 13px; background:var(--bg-hover);">${h}</th>`).join('')}</tr></thead>`;
            
            const rows = body.trim().split(/\r?\n/);
            const rowsHtml = rows.map(row => {
                const cells = getCells(row);
                return `<tr>${cells.map(c => `<td style="border:1px solid var(--border); padding:6px 13px;">${c}</td>`).join('')}</tr>`;
            }).join('');
            
            return `<div style="overflow-x:auto; margin:16px 0;"><table style="width:100%; border-collapse:collapse; border:1px solid var(--border); font-size:13px; background:var(--bg-card);">${headerHtml}<tbody>${rowsHtml}</tbody></table></div>`;
        });

        // 10. 换行处理
        html = html.replace(/\n/g, '<br>');
        
        return html;
    }
};
